1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.LocalDate;
7	import java.util.Map;
8	
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	
11	/**
12	 * Single source of truth for an owner's {@code memberId}, the unified identity
13	 * {@code '<REGION><FY><HASH8><CHK>'} where:
14	 *
15	 * <ul>
16	 *   <li>{@code REGION} is the region code derived from the postcode range (NSW 2000-2099,
17	 *       VIC 3000-3099, QLD 4000-4099), falling back to the city table (Sydney→NSW, Melbourne→VIC,
18	 *       Brisbane→QLD) and finally {@code 'UNKNOWN'};</li>
19	 *   <li>{@code FY} is the two-digit fiscal year (the last two digits of the fiscal year, starting
20	 *       1 July, that contains the registrationDate — the same year segment as
21	 *       {@link org.springframework.samples.petclinic.mapper.OwnerMapper#fiscalYear});</li>
22	 *   <li>{@code HASH8} is the first 8 upper-case hex characters of the SHA-256 of
23	 *       {@code normalizedTelephone + lastName} (the same HASH8 used by the region-and-hash
24	 *       identity); and</li>
25	 *   <li>{@code CHK} is a single Luhn check digit (0-9) computed over the digits of
26	 *       {@code <REGION><FY><HASH8>}.</li>
27	 * </ul>
28	 *
29	 * <p>There is no per-city sequence: two owners with the same normalized telephone, last name,
30	 * region and fiscal year derive the same memberId. Everything downstream of the identity — the
31	 * create audit line and the {@code locality} — is derived from the same region (see
32	 * {@link org.springframework.samples.petclinic.mapper.OwnerMapper}).
33	 */
34	public final class MemberId {
35	
36	    /** Fixed city-to-region table backing the {@code REGION} fallback when the postcode resolves none. */
37	    private static final Map<String, String> CITY_REGIONS = Map.of(
38	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
39	
40	    private MemberId() {
41	    }
42	
43	    /**
44	     * The full {@code '<REGION><FY><HASH8><CHK>'} memberId for the given normalized telephone, last
45	     * name, postcode, city and registrationDate.
46	     */
47	    public static String of(String normalizedTelephone, String lastName, String postcode, String city,
48	            LocalDate registrationDate) {
49	        String base = region(postcode, city) + fiscalYearSegment(registrationDate)
50	                + hash8(normalizedTelephone, lastName);
51	        return base + luhn(base);
52	    }
53	
54	    /**
55	     * Derives {@code REGION}: the postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
56	     * then the {@link #CITY_REGIONS} city table, then {@code 'UNKNOWN'}. This disambiguates cities that
57	     * share a name and is the region embedded in every {@code memberId}.
58	     */
59	    public static String region(String postcode, String city) {
60	        String region = regionForPostcode(postcode);
61	        if (region != null) {
62	            return region;
63	        }
64	        return CITY_REGIONS.getOrDefault(city, "UNKNOWN");
65	    }
66	
67	    /** {@code HASH8}: the first 8 upper-case hex characters of SHA-256 of {@code normalizedTelephone + lastName}. */
68	    public static String hash8(String normalizedTelephone, String lastName) {
69	        String tel = normalizedTelephone == null ? "" : normalizedTelephone;
70	        String last = lastName == null ? "" : lastName;
71	        return shaHex(tel + last, 8);
72	    }
73	
74	    /** The two-digit fiscal-year segment for {@code registrationDate}, or {@code "00"} when absent. */
75	    private static String fiscalYearSegment(LocalDate registrationDate) {
76	        if (registrationDate == null) {
77	            return "00";
78	        }
79	        return String.format("%02d", OwnerMapper.fiscalYearEnding(registrationDate) % 100);
80	    }
81	
82	    /** Single Luhn check digit (0-9) over the digits contained in {@code value}. */
83	    private static int luhn(String value) {
84	        int sum = 0;
85	        boolean dbl = true;
86	        for (int i = value.length() - 1; i >= 0; i--) {
87	            char c = value.charAt(i);
88	            if (c < '0' || c > '9') {
89	                continue;
90	            }
91	            int d = c - '0';
92	            if (dbl) {
93	                d *= 2;
94	                if (d > 9) {
95	                    d -= 9;
96	                }
97	            }
98	            sum += d;
99	            dbl = !dbl;
100	        }
101	        return (10 - (sum % 10)) % 10;
102	    }
103	
104	    /**
105	     * Derives the region from a 4-digit postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
106	     * Returns {@code null} when the postcode is absent, non-numeric or in no known range.
107	     */
108	    private static String regionForPostcode(String postcode) {
109	        if (postcode == null) {
110	            return null;
111	        }
112	        int code;
113	        try {
114	            code = Integer.parseInt(postcode.trim());
115	        } catch (NumberFormatException ex) {
116	            return null;
117	        }
118	        if (code >= 2000 && code <= 2099) {
119	            return "NSW";
120	        }
121	        if (code >= 3000 && code <= 3099) {
122	            return "VIC";
123	        }
124	        if (code >= 4000 && code <= 4099) {
125	            return "QLD";
126	        }
127	        return null;
128	    }
129	
130	    /** First {@code n} upper-case hex characters of SHA-256 of {@code value}. */
131	    private static String shaHex(String value, int n) {
132	        try {
133	            byte[] digest = MessageDigest.getInstance("SHA-256")
134	                    .digest(value.getBytes(StandardCharsets.UTF_8));
135	            StringBuilder sb = new StringBuilder(digest.length * 2);
136	            for (byte b : digest) {
137	                sb.append(String.format("%02X", b));
138	            }
139	            return sb.substring(0, n);
140	        }
141	        catch (NoSuchAlgorithmException e) {
142	            throw new IllegalStateException("SHA-256 not available", e);
143	        }
144	    }
145	}
