52	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
53	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
54	        boolean disposableAdjacent = org.springframework.samples.petclinic.rest.function.owner.OwnerEmail
55	                .isDisposableAdjacent(owner.getEmail());
56	        return possibleDuplicate || disposableAdjacent || overSoftCapacity;
