97	    /**
98	     * The fixed set of known regions (localities) treated as METRO; any other locality
99	     * (including 'UNKNOWN') is REGIONAL.
100	     */
101	    Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
102	
103	    /**
104	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
105	     * {@code 'PREMIUM'} when {@link #membershipLevel(Owner)} is 3 or more, otherwise
106	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the {@link #locality(Owner)} is a known
107	     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'} — so the result is one of
108	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
109	     * {@code 'STANDARD_REGIONAL'}.
