139	            return null;
140	        }
141	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
142	        if (age < 18) {
143	            return "MINOR";
144	        }
145	        if (age < 65) {
146	            return "ADULT";
