153	     * through: the SHA-256 hex of {@code normalizedTelephone|lowerEmail|soundex(lastName)}
154	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity}).
155	     */
156	    default String identityKey(Owner owner) {
157	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity
