163	     * humans as the country code, a space, then the national digits grouped left-to-right in threes
164	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The known country codes are
165	     * {@code +61} (2 digits, matching the normalization in
166	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerFields}) and
167	     * {@code +1} (1 digit); any other leading digit is treated as a two-digit country code. Returns
168	     * {@code null} when the telephone is absent or not a {@code +}-prefixed run of digits, so the raw
169	     * {@code telephone} is left untouched in E.164 form.
170	     */
171	    default String telephoneDisplay(Owner owner) {
172	        String telephone = owner.getTelephone();
173	        if (telephone == null || !telephone.startsWith("+")) {
174	            return null;
175	        }
176	        String digits = telephone.substring(1);
177	        if (!digits.matches("\\d+")) {
178	            return null;
179	        }
180	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
181	        if (digits.length() <= countryCodeLength) {
