196	    /**
197	     * Fixed region-to-timezone table mapping each locality (region) to its IANA timezone name.
198	     */
199	    Map<String, String> REGION_TIMEZONE = Map.of(
200	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
201	
202	    /**
203	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's {@link #locality(Owner)}
204	     * (region) from the fixed region-to-timezone table (NSW→Australia/Sydney, VIC→Australia/Melbourne,
