233	    /**
234	     * Derives the owner's membership points: starting at 0, plus 2 when an email is present, plus 1
235	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more (its
236	     * {@code householdMemberCount}), plus 3 when the owner's tenure — the number of fiscal years
237	     * (starting 1 July) elapsed between {@code registrationDate} and today — exceeds 1.
238	     */
239	    static Integer membershipPoints(Owner owner) {
240	        return membershipPoints(owner, owner.getHouseholdMemberCount());
241	    }
242	
243	    /**
244	     * As {@link #membershipPoints(Owner)}, but scoring the "household of 3 or more" bonus against the
245	     * supplied {@code householdMemberCount} rather than the owner's stored one. Used when evaluating an
246	     * existing household member against the household as it stands <em>now</em> (see
247	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}), since a
248	     * member's own count is frozen at its own create time.
249	     */
250	    static Integer membershipPoints(Owner owner, Integer householdMemberCount) {
251	        int points = 0;
252	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
253	        if (hasEmail) {
254	            points += 2;
255	        }
256	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
257	        if (noNamesakes) {
258	            points += 1;
259	        }
260	        boolean largeHousehold = householdMemberCount != null && householdMemberCount >= 3;
261	        if (largeHousehold) {
262	            points += 2;
263	        }
264	        boolean tenured = owner.getRegistrationDate() != null
265	                && (fiscalYearEnding(java.time.LocalDate.now())
266	                        - fiscalYearEnding(owner.getRegistrationDate())) > 1;
267	        if (tenured) {
268	            points += 3;
269	        }
270	        return points;
271	    }
272	
273	    /**
274	     * The owner's effective membership level. When a level has been stored on the entity (assigned at
275	     * create time by
276	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}, which
277	     * applies the household level ceiling) that value stands; otherwise it falls back to the level
278	     * derived directly from points (see {@link #derivedMembershipLevel(Owner)}), so seed owners
279	     * without a stored level still map cleanly.
280	     */
281	    static Integer membershipLevel(Owner owner) {
282	        if (owner.getMembershipLevel() != null) {
283	            return owner.getMembershipLevel();
284	        }
285	        return derivedMembershipLevel(owner);
286	    }
287	
288	    /**
289	     * Derives the owner's membership level from 1 to 4 by mapping {@link #membershipPoints(Owner)}:
290	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. This is the uncapped level, before
291	     * the household ceiling applied at create time.
292	     */
293	    static Integer derivedMembershipLevel(Owner owner) {
294	        return levelForPoints(membershipPoints(owner));
295	    }
296	
297	    /**
298	     * As {@link #derivedMembershipLevel(Owner)}, but scoring the household bonus against the supplied
299	     * {@code householdMemberCount} — the household's current size — rather than the owner's frozen one.
300	     */
301	    static Integer derivedMembershipLevel(Owner owner, Integer householdMemberCount) {
302	        return levelForPoints(membershipPoints(owner, householdMemberCount));
303	    }
304	
305	    private static Integer levelForPoints(int points) {
306	        if (points >= 6) {
307	            return 4;
308	        }
309	        if (points >= 4) {
310	            return 3;
311	        }
312	        if (points >= 2) {
313	            return 2;
314	        }
315	        return 1;
316	    }
317	
318	    Owner toOwner(OwnerDto ownerDto);
319	
320	    @Mapping(target = "id", ignore = true)
321	    @Mapping(target = "pets", ignore = true)
322	    @Mapping(target = "memberId", ignore = true)
323	    @Mapping(target = "householdId", ignore = true)
324	    @Mapping(target = "namesakeCount", ignore = true)
325	    @Mapping(target = "householdMemberCount", ignore = true)
326	    @Mapping(target = "possibleDuplicate", ignore = true)
327	    @Mapping(target = "possibleDuplicateOf", ignore = true)
328	    @Mapping(target = "membershipLevel", ignore = true)
329	    @Mapping(target = "deleted", ignore = true)
330	    Owner toOwner(OwnerFieldsDto ownerDto);
331	
332	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
333	
334	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
335	
336	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
337	        OwnerPageDto ownerPageDto = new OwnerPageDto();
338	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
339	        ownerPageDto.setPage(ownerPage.getNumber());
340	        ownerPageDto.setSize(ownerPage.getSize());
341	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
342	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
343	        return ownerPageDto;
344	    }
345	}
