    /**
     * Fixed region-to-timezone table mapping each locality (region) to its IANA timezone name.
     */
    Map<String, String> REGION_TIMEZONE = Map.of(
            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");

