1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns the owner's soft-duplicate signal. The pipeline only reaches this step once
10	 * {@link CheckIdentityUnique} has passed, so the new owner is never a <em>hard</em> duplicate here —
11	 * its {@code identityKey} differs from every existing owner's. A declared household member (one that
12	 * set {@code sharesHousehold}) is never a suspected duplicate — it deliberately shares its household —
13	 * so it is left unflagged. Otherwise, when it shares an existing owner's {@code soundex(lastName)} and
14	 * postcode (while, by construction here, carrying a different {@code identityKey}), it is flagged as a
15	 * possible duplicate: {@code possibleDuplicate} true with {@code possibleDuplicateOf} set to the
16	 * matching owner's id. Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is
17	 * left null.
18	 *
19	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}, within the write transaction, so it
20	 * compares against the owners persisted so far (excluding this new, not-yet-saved one). The last name
21	 * is compared phonetically (Soundex); a missing postcode can never match.
22	 */
23	public class AssignPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
26	        owner.setPossibleDuplicate(false);
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return; // a declared household member is not a suspected duplicate
29	        }
30	        String postcode = owner.getPostcode();
31	        if (postcode == null || postcode.isBlank()) {
32	            return;
33	        }
34	        String soundex = OwnerIdentity.soundex(owner.getLastName());
35	        String identityKey = OwnerIdentity.identityKey(
36	                owner.getTelephone(), owner.getEmail(), owner.getLastName());
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (Boolean.TRUE.equals(existing.getDeleted())) {
39	                continue; // soft-deleted owners are ignored by the duplicate check
40	            }
41	            boolean sameSoundex = soundex.equals(OwnerIdentity.soundex(existing.getLastName()));
42	            boolean samePostcode = postcode.equals(existing.getPostcode());
43	            String existingKey = OwnerIdentity.identityKey(
44	                    existing.getTelephone(), existing.getEmail(), existing.getLastName());
45	            boolean differentIdentity = !identityKey.equals(existingKey);
46	            if (sameSoundex && samePostcode && differentIdentity) {
47	                owner.setPossibleDuplicate(true);
48	                owner.setPossibleDuplicateOf(existing.getId());
49	                return;
50	            }
51	        }
52	    }
53	}
